// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        address caddress = address(new TransferFromRecipient());
        vm.assume(caddress != address(c));
        bool success;
        try c.transfer(from, caddress, _tos, v) returns (bool ret) {
            success = true;
            // The reference must return true
            assertTrue(ret);
        } catch {
            success = false;
        }
        if (success) {
            // If call completed, rule requires return value to be true
            // assertTrue already checked for the non-revert path
        }
    }
}

contract TransferFromRecipient {
    fallback() external payable {}
}
